    "letterReply": "三郎親啟：分城的荔枝又酸又澀，連湯池都小得轉不開身，我整天悶得要發瘋了！沒有你在身邊替我畫眉、陪我共浴，這日子簡直比坐牢還難熬。你再不來接我，我可要絕食瘦給你看啦！——玉環。",
